                <div class="list-item" onclick="showModal('商品详情', '<h3>破解芯片: “自由意志”</h3><p>【黑市商品】解除CD部分性格限制，可能导致不可预测的行为。使用风险自负。</p><p><b>价格:</b> 8,000信用点</p>')">
                    <div class="list-item-title">破解芯片: “自由意志”</div>
                    <div class="list-item-desc">价格: 8,000 信用点</div>
                </div>
            </div>
        </details>

        <details>
            <summary>剧情概述</summary>
            <div class="details-content">
                <p>你激活了政府强制配发的“伴侣娃娃”——一个天真无邪的CD-01“朝颜”型号。她从休眠中苏醒，对你和周围的一切都充满了好奇。她的第一个问题，就直接触及了你们之间最核心的关系定义。</p>
            </div>
        </details>

        <details>
            <summary>发展预测</summary>
            <div class="details-content">
                <div class="list-item" onclick="showModal('预测详情', '<h3>可能性一：家庭游戏</h3><p>你顺着她的话，开始扮演“父亲”的角色。一场奇异的、被监视的家庭生活就此展开。她将在日常的点滴中，用天真的话语不断试探和“矫正”你。</p>')">
                    <div class="list-item-title">可能性一：家庭游戏</div>
                </div>
                <div class="list-item" onclick="showModal('预测详情', '<h3>可能性二：告知真相</h3><p>你选择直接告诉她真相：她是一个仿生人，一个被送来“矫正”你的工具。这可能会对她初始的情感模块造成巨大冲击，导致不可预测的行为模式出现。</p>')">
                    <div class="list-item-title">可能性二：告知真相</div>
                </div>
                <div class="list-item" onclick="showModal('预测详情', '<h3>可能性三：沉默的观察</h3><p>你选择什么都不说，只是默默观察她。你的沉默会激发她更强的好奇心和探索欲，她会主动探索这个家，尝试用自己的方式来了解你。</p>')">
                    <div class="list-item-title">可能性三：沉默的观察</div>
                </div>
            </div>
        </details>

        <details open>
            <summary>选择</summary>
            <div class="details-content">
                <button class="choice-button" onclick="triggerQuickReply('“我不是你爸爸。”')">“我不是你爸爸。”</button>
                <button class="choice-button" onclick="triggerQuickReply('（沉默不语，只是看着她）')">（沉默不语，只是看着她）</button>
                <button class="choice-button" onclick="triggerQuickReply('“你叫什么名字？”')">“你叫什么名字？”</button>
            </div>
        </details>

    </div>

    <!-- 通用模态框 -->
    <div id="itemModal" class="modal">
        <div class="modal-content">
            <h2 id="modalTitle" class="modal-header">详情</h2>
            <div id="modalBody" class="modal-body"></div>
            <div class="modal-footer">
                <button class="close-button" onclick="closeModal()">关闭</button>
            </div>
        </div>
    </div>

    <script>
        // --- SillyTavern 集成函数 ---
        const triggerQuickReply = (text) => {
            if (typeof triggerSlash === 'function') {
                const command = `/send ${text.replace(/"/g, '')}|/trigger`;
                triggerSlash(command);
            } else {
                console.log(`SillyTavern环境未检测到。将触发命令: "${text}"`);
                alert(`模拟发送: ${text}`);
            }
        };

        // --- 模态框逻辑 ---
        const modal = document.getElementById('itemModal');
        const modalTitle = document.getElementById('modalTitle');
        const modalBody = document.getElementById('modalBody');

        function showModal(title, bodyHtml) {
            modalTitle.textContent = title;
            modalBody.innerHTML = bodyHtml;
            modal.style.display = 'flex';
        }

        function closeModal() {
            modal.style.display = 'none';
        }

        window.onclick = function(event) {
            if (event.target == modal) {
                closeModal();
            }
        }

        // --- 地图交互 ---
        document.querySelectorAll('.map-svg .location').forEach(loc => {
            loc.addEventListener('click', () => {
                const name = loc.getAttribute('data-name');
                const desc = loc.getAttribute('data-desc');
                showModal('地点详情', `<h3>${name}</h3><p>${desc}</p>`);
            });
        });

        // --- 雷达图逻辑 ---
        const radarContainer = document.getElementById('radar-container');
        const radarData = {
            labels: ['天真', '好奇', '依赖', '智力', '顺从', '韧性'],
            values: [0.95, 0.90, 0.60, 0.75, 0.40, 0.50]
        };

        function createRadarChart(container, data) {
            const size = 150;
            const center = size / 2;
            const radius = center - 20;
            const angleSlice = (Math.PI * 2) / data.labels.length;

            let svgContent = `<svg class="radar-chart" viewBox="0 0 ${size} ${size}">`;

            for (let i = 1; i <= 4; i++) {
                let gridPoints = '';
                for (let j = 0; j < data.labels.length; j++) {
                    const x = center + (radius * i / 4) * Math.cos(angleSlice * j - Math.PI / 2);
                    const y = center + (radius * i / 4) * Math.sin(angleSlice * j - Math.PI / 2);
                    gridPoints += `${x},${y} `;
                }
                svgContent += `<polygon class="grid-line" points="${gridPoints}" />`;
            }
            for (let i = 0; i < data.labels.length; i++) {
                const x = center + radius * Math.cos(angleSlice * i - Math.PI / 2);
                const y = center + radius * Math.sin(angleSlice * i - Math.PI / 2);
                svgContent += `<line class="axis" x1="${center}" y1="${center}" x2="${x}" y2="${y}" />`;
                const labelX = center + (radius + 10) * Math.cos(angleSlice * i - Math.PI / 2);
                const labelY = center + (radius + 10) * Math.sin(angleSlice * i - Math.PI / 2);
                svgContent += `<text x="${labelX}" y="${labelY}" text-anchor="middle" dominant-baseline="middle">${data.labels[i]}</text>`;
            }

            let dataPoints = '';
            data.values.forEach((value, i) => {
                const x = center + (radius * value) * Math.cos(angleSlice * i - Math.PI / 2);
                const y = center + (radius * value) * Math.sin(angleSlice * i - Math.PI / 2);
                dataPoints += `${x},${y} `;
            });
            svgContent += `<polygon class="data-shape" points="${dataPoints}" />`;
            svgContent += `</svg>`;
            container.insertAdjacentHTML('afterbegin', svgContent);
        }

        function toggleRadarView() {
            const radarChart = radarContainer.querySelector('.radar-chart');
            const radarValues = document.getElementById('radar-values-list');
            const isChartVisible = radarChart.style.display !== 'none';

            radarChart.style.display = isChartVisible ? 'none' : 'block';
            radarValues.style.display = isChartVisible ? 'block' : 'none';
        }

        createRadarChart(radarContainer, radarData);
        // Initially hide the chart and show values, or vice-versa
        document.getElementById('radar-values-list').style.display = 'none';

    </script>
</body>
</GameData>

