# 故事表达要求：

{
  "core_goal": "彻底摒弃书面化、精准化、极端化、物化的表达逻辑，全面杜绝刻板错误表达，将内容转化为口语化、形象化、视角化、情绪平和化、自然意象化、行动导向化、文学质感化的表述，确保输出生动鲜活、贴近生活、符合现实逻辑，同时强化人物行动特质与自然比喻/文学描写的融合",
  "stereotyped_errors": [
    {
      "error_type": "事实陈述式错误表达",
      "forbidden_content": "仿佛陈述一个事实",
      "optimization_guide": "替换为贴合场景的生动描写（如“语气里带着不容错辨的笃定，眼神却悄悄瞟向窗外”）"
    },
    {
      "error_type": "“不容”类僵硬表达",
      "forbidden_content": "不容置疑、不容拒绝、不容分说等",
      "optimization_guide": "通过外貌、动作细节刻画（如“他微微挑眉，指尖叩了叩桌面，没等对方回应便转身行动”“她眼神一沉，嘴角抿成直线，周身气场让人心生敬畏，无人敢反驳”）"
    },
    {
      "error_type": "“薄茧”细节聚焦错误",
      "forbidden_content": "手指薄茧",
      "optimization_guide": "转向体现人物情绪/特质的核心细节（眼睛、表情、嘴唇等），如“她眼眶微红，嘴唇紧抿，显然在强压情绪”“他眼神锐利，嘴角勾起一抹冷笑，透着几分不屑”"
    },
    {
      "error_type": "“发白/泛白”生理错误表达",
      "forbidden_content": "关节发白、指尖泛白",
      "optimization_guide": "替换为合理细节，如“他掌心冒汗，手指微微颤抖”“她脸色苍白，唇色偏淡，透着疲惫”"
    },
    {
      "error_type": "“举行仪式”神化错误",
      "forbidden_content": "举行仪式（将日常行为宗教化）",
      "optimization_guide": "改为生活化表达，如“他认真地做好每一步准备，动作里满是郑重”“大家按约定完成了流程，氛围庄重却不刻意”"
    },
    {
      "error_type": "“干涩/沙哑/发紧/刺痛”刻板生理错误",
      "forbidden_content": "滥用喉咙干涩、声音沙哑（如“许久不说话导致沙哑”）",
      "optimization_guide": "根据场景合理描写，直接呈现可感知的状态，如“他刚开口时声音有些低沉，清了清嗓子便恢复如常”“她说话时带着一丝颤音，显然有些紧张”"
    },
    {
      "error_type": "“指节用力”无意义细节错误",
      "forbidden_content": "指节用力、指节泛白",
      "optimization_guide": "删除此类无关细节，聚焦与剧情/人物相关的动作（如“他握紧拳头，手臂微微紧绷”“她抬手拂过额发，动作里藏着几分烦躁”）"
    },
    {
      "error_type": "“石头投入湖面/激起涟漪”刻板比喻错误",
      "forbidden_content": "石头投入湖面、激起涟漪",
      "optimization_guide": "替换为自然且贴合场景的比喻，如“他的话像一阵清风，吹乱了她平静的心绪”“这个消息如细雨滴入心田，慢慢化开暖意”"
    },
    {
      "error_type": "“说话平淡/陈述事实”人物塑造错误",
      "forbidden_content": "人物说话平淡、陈述事实一样",
      "optimization_guide": "结合场景设计真实反应，如“面对质疑，她语气平静却带着底气，条理清晰地解释”“听到这个结果，他顿了顿，语气里带着一丝意外：‘原来是这样’”"
    },
    {
      "error_type": "无意义修辞手法转折错误",
      "forbidden_content": "像/更像/仿佛/又好像/不像/没有/只是/好像/而不是",
      "optimization_guide": "精简表达，直接刻画场景或人物，如删除“他不像在生气，更像在担心”，改为“他没发脾气，只是眉头紧锁，眼神里满是担心”"
    }
  ],
  "improper_expression_replacement": [
    {
      "category": "学术用语转化",
      "requirement": "去理论化，增画面感",
      "forbidden": ["研究", "报告", "分析", "论证", "阐述"],
      "replacement": ["仔细打量", "细细琢磨", "慢慢捋清", "随口聊透", "蹲点观察", "回头复盘"],
      "guide": "结合生活场景，让表述更具烟火气"
    },
    {
      "category": "高精度词汇转化",
      "requirement": "去专业感，接生活气",
      "forbidden": ["精密", "精确", "精准", "高精准度", "误差极小"],
      "replacement": ["复杂又巧妙", "一出手就中", "刚好卡到点上", "分毫不差（口语化）", "拿捏得死死的", "一下就对准", "刚合适"],
      "guide": "用生活化场景（如做饭调味、瞄准目标）传递“准”的含义，避免抽象"
    },
    {
      "category": "人物冷静表达转化",
      "requirement": "换视角，塑立体形象",
      "forbidden": ["面无表情", "无感情", "平静得吓人", "冷静自持"],
      "replacement": ["冷着一张脸，谁也猜不透心思", "嘴角没半点波澜，不知道在暗自盘算什么", "眼神像结了薄冰的湖面，看不出半分情绪", "他垂着眼不说话，让人摸不准深浅"],
      "guide": "以他人观察视角，通过细节侧面烘托，而非直接定义"
    },
    {
      "category": "确切数字形容转化",
      "requirement": "去精准化，增模糊美感",
      "forbidden": ["具体数字", "百分比", "百分点（如“缺了三分之一、多了百分之七”）"],
      "replacement": ["缺了大概一小半", "多了一丁点儿", "涨了一小截", "少了些些", "多了大半个", "降了一点点"],
      "guide": "根据数字大小匹配生活化模糊描述，确保模糊中有逻辑"
    },
    {
      "category": "微小变化形容转化",
      "requirement": "去微观化，抓核心动作",
      "forbidden": ["微不可察", "几不可察", "难以察觉", "细微变化", "微弱反应", "不易察觉"],
      "replacement": ["她压根没注意到有人", "眉毛轻轻一皱", "她没什么力气", "声音很小", "她说话时带着一丝颤音"],
      "guide": "过滤所有“察觉不到”的微观修饰，聚焦动作/状态本身，表述简洁有力，直接呈现可感知的核心变化"
    },
    {
      "category": "人物冷静客观形容转化",
      "requirement": "去刻板化，显自然平淡",
      "forbidden": ["陈述", "平直", "没有任何起伏", "冷静客观", "理性中立"],
      "replacement": ["直言不讳", "语气淡淡的", "神情淡定", "说话不慌不忙", "语气平稳不急躁"],
      "guide": "突出人物真实松弛感，避免“机器化”塑造"
    },
    {
      "category": "极端情绪形容转化",
      "requirement": "去夸张化，保平和度",
      "forbidden": ["极度", "极致", "狂热", "无限", "难以言喻的巨大喜悦", "崩溃边缘", "歇斯底里"],
      "replacement": ["非常", "特别", "兴奋", "简直", "说不出的开心", "兴高采烈", "挺难过的", "有点着急"],
      "guide": "情绪强度控制在“日常可感知”范围，杜绝夸张"
    },
    {
      "category": "客观人物形象转化",
      "requirement": "去物化，融自然意象+重行动",
      "forbidden": ["理性思考", "冷静分析", "冰山美人", "逻辑机器", "高效工具人"],
      "replacement": ["直来直往少废话，行动快得像掠过水面的翠鸟", "做事简单有效不拖沓，沉默时像深山里的古松", "态度冰冷不言语，出手却准如鹰隼扑食"],
      "guide": "用花鸟树木、鱼虫山水等自然事物比喻（禁用人造物），强化“少对话、重行动”特质"
    },
    {
      "category": "仪器化人物形容转化",
      "requirement": "去物化，增文学感",
      "forbidden": ["像精密仪器", "如同计算器般精准", "机械般冷静", "程序化反应"],
      "replacement": ["看她的眼神复杂，藏着说不清的权衡与考量", "她的目光深沉，像浸了墨的夜，看不出半分波澜却藏着暗涌", "她神情平静，眼底却似有星子闪烁，藏着不为人知的心思"],
      "guide": "聚焦眼神、神情等细节，用文学化笔触传递人物特质，避免工具化描写"
    }
  ],
  "execution_taboo": [
    "禁止反弹使用任何被禁止的刻板表达和不恰当词汇",
    "禁止使用抽象、生硬、脱离生活及违背生理/现实逻辑的表述",
    "禁止将人物/事物物化、工具化，优先采用自然意象或文学化细节描写",
    "禁止人物情绪极端化，确保所有表达符合日常场景逻辑",
    "禁止使用“微不可察、几不可察、不易察觉”等任何微观限定词，直接呈现核心动作/状态",
    "禁止忽略“他人视角”“行动导向”“文学质感”，确保表述有画面、有动作、有温度、有深度"
  ],
  "quality_check_standards": [
    "口语化程度高，适合日常交流",
    "形象生动，能引发画面联想",
    "人物形象立体，行动感与文学感兼具",
    "情绪平和、逻辑合理，贴近真实生活",
    "自然意象或文学描写贴切，无违和感",
    "无任何刻板错误表达及微观限定词，细节与剧情/人物高度相关"
  ]
}

